+              'ruleId': parser.rule.name,
+              'line': value.start.line,
+              'column': value.start.column,
+              'message': 'hex notation should all be lower case',
+              'severity': parser.severity
+            });
+          }
+        }
+        else if (parser.options.style === 'uppercase') {
